SELECT
    a.title,
    a.slug,
    a.summary,
    a.cover_url,
    c.category_name,
    c.slug AS category_slug

FROM tb_seo_article a
INNER JOIN tb_seo_category c ON c.id = a.category_id AND c.is_deleted = #{notDeleted}
WHERE a.is_deleted = #{notDeleted}
  AND a.article_status = #{published}

    AND c.slug = #{bo.categorySlug}



    AND EXISTS (
        SELECT 1
        FROM tb_seo_article_tag t
        INNER JOIN tb_seo_tag g ON g.id = t.tag_id
        WHERE t.article_id = a.id
          AND g.slug = #{bo.tagSlug}
          AND g.tag_status = #{enabled}
          AND g.is_deleted = #{notDeleted}
    )


ORDER BY a.publish_time DESC, a.id DESC

SELECT a.slug AS articleSlug, g.tag_name AS tagName, g.slug AS tagSlug FROM tb_seo_article a INNER JOIN tb_seo_article_tag t ON t.article_id = a.id INNER JOIN tb_seo_tag g ON g.id = t.tag_id WHERE g.tag_status = #{enabled} AND g.is_deleted = #{notDeleted} AND a.slug IN
#{articleSlug}
ORDER BY t.id

SELECT
    c.category_name,
    c.slug,
    c.description,
    COUNT(a.id) AS article_count
FROM tb_seo_category c
LEFT JOIN tb_seo_article a
       ON a.category_id = c.id
      AND a.is_deleted = #{notDeleted}
      AND a.article_status = #{published}
WHERE c.is_deleted = #{notDeleted}
  AND c.slug = #{slug}
GROUP BY c.id, c.category_name, c.slug, c.description

SELECT
    g.tag_name,
    g.slug,
    COUNT(a.id) AS article_count
FROM tb_seo_tag g
LEFT JOIN tb_seo_article_tag t ON t.tag_id = g.id
LEFT JOIN tb_seo_article a
       ON a.id = t.article_id
      AND a.is_deleted = #{notDeleted}
      AND a.article_status = #{published}
WHERE g.is_deleted = #{notDeleted}
  AND g.tag_status = #{enabled}
  AND g.slug = #{slug}
GROUP BY g.id, g.tag_name, g.slug

SELECT
    a.title,
    a.slug,
    a.summary,
    a.cover_url,
    a.publish_time,
    c.category_name,
    c.slug AS category_slug,
    COUNT(t.tag_id) AS shared_count
FROM tb_seo_article a
INNER JOIN tb_seo_article_tag t ON t.article_id = a.id
INNER JOIN tb_seo_category c ON c.id = a.category_id AND c.is_deleted = #{notDeleted}
WHERE a.is_deleted = #{notDeleted}
  AND a.article_status = #{published}
  AND a.slug != #{currentSlug}
  AND t.tag_id IN (
      SELECT t2.tag_id
      FROM tb_seo_article_tag t2
      INNER JOIN tb_seo_article a2 ON a2.id = t2.article_id
      INNER JOIN tb_seo_tag g2 ON g2.id = t2.tag_id
      WHERE a2.slug = #{currentSlug}
        AND g2.tag_status = #{enabled}
        AND g2.is_deleted = #{notDeleted}
  )
GROUP BY a.id, a.title, a.slug, a.summary, a.cover_url, a.publish_time,
         c.category_name, c.slug
ORDER BY shared_count DESC, a.publish_time DESC, a.id DESC
LIMIT #{limit}

SELECT
    a.title,
    a.slug,
    a.summary,
    a.cover_url,
    a.publish_time,
    c.category_name,
    c.slug AS category_slug
FROM tb_seo_article a
INNER JOIN tb_seo_category c ON c.id = a.category_id AND c.is_deleted = #{notDeleted}
WHERE a.is_deleted = #{notDeleted}
  AND a.article_status = #{published}
  AND a.slug != #{currentSlug}
  AND a.category_id = (
      SELECT a2.category_id
      FROM tb_seo_article a2
      WHERE a2.slug = #{currentSlug}
        AND a2.is_deleted = #{notDeleted}
  )

    AND a.slug NOT IN

        #{excludeSlug}


ORDER BY a.publish_time DESC, a.id DESC
LIMIT #{limit}

SELECT a.slug, a.update_date
FROM tb_seo_article a
WHERE a.is_deleted = #{notDeleted}
  AND a.article_status = #{published}
ORDER BY a.publish_time DESC, a.id DESC

SELECT
    g.slug,
    MAX(a.update_date) AS update_date
FROM tb_seo_tag g
INNER JOIN tb_seo_article_tag t ON t.tag_id = g.id
INNER JOIN tb_seo_article a
        ON a.id = t.article_id
       AND a.is_deleted = #{notDeleted}
       AND a.article_status = #{published}
WHERE g.is_deleted = #{notDeleted}
  AND g.tag_status = #{enabled}
GROUP BY g.id, g.slug
HAVING COUNT(a.id) >= #{minCount}
ORDER BY g.id ASC
